appendSegment(index: number, seg: Segment): Promise<void> {
  const last = this.lastCue;
  // Merge (PLAN-012): a consecutive same-speaker segment folds into the
  // last cue while the resulting span stays under the threshold. The cue
  // keeps its original number; the absorbed index leaves a numbering gap.
  if (
    this.mergeMaxS > 0 &&
    last !== undefined &&
    seg.speaker === last.speaker &&
    seg.end_s - last.start_s < this.mergeMaxS
  ) {
    this.cueOfIndex.set(index, last.cueNo);
    this.mergedCues.add(last.cueNo);
    last.end_s = seg.end_s;
    const cueNo = last.cueNo;
    return this.enqueue(async () => {
      const srt = await fs.readFile(this.srtPath, 'utf8');
      const extended = extendCue(srt, cueNo - 1, seg.end_s, seg.text);
      if (extended === null) {
        this.log.warn(
          `segment ${index} not merged: cue ${cueNo} missing`,
        );
        return;
      }
      const tmp = `${this.srtPath}.tmp`;
      await fs.writeFile(tmp, extended);
      await fs.rename(tmp, this.srtPath);
    });
  }
  const speakerName = seg.speaker
    ? (this.meta.speakers[seg.speaker] ?? seg.speaker)
    : undefined;
  const cue = formatCue(index, seg, speakerName);
  this.cueOfIndex.set(index, index + 1);
  this.lastCue = {
    cueNo: index + 1,
    speaker: seg.speaker,
    start_s: seg.start_s,
    end_s: seg.end_s,
  };
  return this.enqueue(() => fs.appendFile(this.srtPath, cue));
}

// Translations land after newer cues may already exist, so this is a
// read -> splice -> tmp+rename cycle, serialized on the same queue as the
// appends. A missing or already-translated cue logs and skips. A cue
// built by merging collects the translations of every contributing
// index, joined in index order, so the last text line is rewritten
// rather than skipped once translated.
appendTranslation(index: number, text: string): Promise<void> {
  const cueNo = this.cueOfIndex.get(index) ?? index + 1;
  if (this.mergedCues.has(cueNo)) {
    let perCue = this.cueTranslations.get(cueNo);
    if (!perCue) {
      perCue = new Map();
      this.cueTranslations.set(cueNo, perCue);
    }
    perCue.set(index, text);
    return this.enqueue(async () => {
      const joined = [...perCue.entries()]
        .sort(([a], [b]) => a - b)
        .map(([, t]) => t)
        .join(' ');
      const srt = await fs.readFile(this.srtPath, 'utf8');
      const rewritten = setCueTranslation(srt, cueNo - 1, joined);
      if (rewritten === null) {
        this.log.warn(
          `translation for segment ${index} not written: cue ${cueNo} missing`,
        );
        return;
      }
      const tmp = `${this.srtPath}.tmp`;
      await fs.writeFile(tmp, rewritten);
      await fs.rename(tmp, this.srtPath);
    });
  }
  return this.enqueue(async () => {
    const srt = await fs.readFile(this.srtPath, 'utf8');
    const spliced = insertTranslationLine(srt, cueNo - 1, text);
    if (spliced === null) {
      this.log.warn(
        `translation for segment ${index} not written: cue missing or already translated`,
      );
      return;
    }
    let perCue = this.cueTranslations.get(cueNo);
    if (!perCue) {
      perCue = new Map();
      this.cueTranslations.set(cueNo, perCue);
    }
    perCue.set(index, text);
    const tmp = `${this.srtPath}.tmp`;
    await fs.writeFile(tmp, spliced);
    await fs.rename(tmp, this.srtPath);
  });
}

