} from './srt.js';

describe('extendCue', () => {
  const srt = [
    '1\n00:00:00,000 --> 00:00:02,000\nSpeaker 1: Hello.',
    '2\n00:00:05,100 --> 00:00:08,200\nHi there.',
    '',
  ].join('\n\n');

  it('extends the end timestamp and appends to the source line', () => {
    expect(extendCue(srt, 0, 3.4, 'there.')).toBe(
