describe('SessionWriter cue merging', () => {
  it('merges consecutive same-speaker segments under the threshold, chaining', async () => {
    const w = await SessionWriter.create(
      dir,
      meta('2026-11-05-session-1000'),
      undefined,
      { mergeMaxS: 10 },
    );
    await w.appendSegment(0, {
      text: 'Hello.',
      speaker: 'Speaker 1',
      start_s: 0,
      end_s: 2,
    });
    await w.appendSegment(1, {
      text: 'there.',
      speaker: 'Speaker 1',
      start_s: 2,
      end_s: 3.4,
    });
    expect(await fs.readFile(w.srtPath, 'utf8')).toBe(
      '1\n00:00:00,000 --> 00:00:03,400\nSpeaker 1: Hello. there.\n\n',
    );

    // a third same-speaker segment extends the same cue again
    await w.appendSegment(2, {
      text: 'again.',
      speaker: 'Speaker 1',
      start_s: 3.4,
      end_s: 5,
    });
    expect(await fs.readFile(w.srtPath, 'utf8')).toBe(
      '1\n00:00:00,000 --> 00:00:05,000\nSpeaker 1: Hello. there. again.\n\n',
    );
  });

  it('keeps a different speaker on its own cue, leaving a numbering gap', async () => {
    const w = await SessionWriter.create(
      dir,
      meta('2026-11-05-session-1000'),
      undefined,
      { mergeMaxS: 10 },
    );
    await w.appendSegment(0, {
      text: 'Hello.',
      speaker: 'Speaker 1',
      start_s: 0,
      end_s: 2,
    });
    await w.appendSegment(1, {
      text: 'there.',
      speaker: 'Speaker 1',
      start_s: 2,
      end_s: 3.4,
    });
    await w.appendSegment(2, {
      text: 'Reply.',
      speaker: 'Speaker 2',
      start_s: 4,
      end_s: 5,
    });
    expect(await fs.readFile(w.srtPath, 'utf8')).toBe(
      '1\n00:00:00,000 --> 00:00:03,400\nSpeaker 1: Hello. there.\n\n' +
        '3\n00:00:04,000 --> 00:00:05,000\nSpeaker 2: Reply.\n\n',
    );
  });

  it('merges speaker-less segments with each other', async () => {
    const w = await SessionWriter.create(
      dir,
      meta('2026-11-05-session-1000'),
      undefined,
      { mergeMaxS: 10 },
    );
    await w.appendSegment(0, { text: 'one', start_s: 0, end_s: 1 });
    await w.appendSegment(1, { text: 'two', start_s: 1, end_s: 2 });
    expect(await fs.readFile(w.srtPath, 'utf8')).toBe(
      '1\n00:00:00,000 --> 00:00:02,000\none two\n\n',
    );
  });

  it('does not merge when the combined span reaches the threshold', async () => {
    const w = await SessionWriter.create(
      dir,
      meta('2026-11-05-session-1000'),
      undefined,
      { mergeMaxS: 5 },
    );
    await w.appendSegment(0, {
      text: 'Hello.',
      speaker: 'Speaker 1',
      start_s: 0,
      end_s: 2,
    });
    // span 0 -> 5 equals the threshold; "under" is strict <
    await w.appendSegment(1, {
      text: 'there.',
      speaker: 'Speaker 1',
      start_s: 2,
      end_s: 5,
    });
    expect(await fs.readFile(w.srtPath, 'utf8')).toBe(
      '1\n00:00:00,000 --> 00:00:02,000\nSpeaker 1: Hello.\n\n' +
        '2\n00:00:02,000 --> 00:00:05,000\nSpeaker 1: there.\n\n',
    );
  });

  it('produces byte-identical output when merging is off', async () => {
    const expected =
      '1\n00:00:00,000 --> 00:00:02,000\nSpeaker 1: Hello.\n\n' +
      '2\n00:00:02,000 --> 00:00:03,400\nSpeaker 1: there.\n\n';
    const segs = [
      { text: 'Hello.', speaker: 'Speaker 1', start_s: 0, end_s: 2 },
      { text: 'there.', speaker: 'Speaker 1', start_s: 2, end_s: 3.4 },
    ];

    const w1 = await SessionWriter.create(dir, meta('2026-11-05-session-1000'));
    await w1.appendSegment(0, segs[0]!);
    await w1.appendSegment(1, segs[1]!);
    expect(await fs.readFile(w1.srtPath, 'utf8')).toBe(expected);

    const w2 = await SessionWriter.create(
      dir,
      meta('2026-11-05-session-1001'),
      undefined,
      { mergeMaxS: 0 },
    );
    await w2.appendSegment(0, segs[0]!);
    await w2.appendSegment(1, segs[1]!);
    expect(await fs.readFile(w2.srtPath, 'utf8')).toBe(expected);
  });

  it('joins translations of merged indices in index order', async () => {
    const w = await SessionWriter.create(
      dir,
      meta('2026-11-05-session-1000'),
      undefined,
      { mergeMaxS: 10 },
    );
    await w.appendSegment(0, {
      text: 'Hello.',
      speaker: 'Speaker 1',
      start_s: 0,
      end_s: 2,
    });
    await w.appendSegment(1, {
      text: 'there.',
      speaker: 'Speaker 1',
      start_s: 2,
      end_s: 3.4,
    });
    await w.appendTranslation(0, 't0');
    await w.appendTranslation(1, 't1');
    expect(await fs.readFile(w.srtPath, 'utf8')).toBe(
      '1\n00:00:00,000 --> 00:00:03,400\nSpeaker 1: Hello. there.\nt0 t1\n\n',
    );
  });

  it('keeps a translation that landed before the merge and joins later ones', async () => {
    const w = await SessionWriter.create(
      dir,
      meta('2026-11-05-session-1000'),
      undefined,
      { mergeMaxS: 10 },
    );
    await w.appendSegment(0, {
      text: 'Hello.',
      speaker: 'Speaker 1',
      start_s: 0,
      end_s: 2,
    });
    await w.appendTranslation(0, 't0');
    await w.appendSegment(1, {
      text: 'there.',
      speaker: 'Speaker 1',
      start_s: 2,
      end_s: 3.4,
    });
    await w.appendTranslation(1, 't1');
    expect(await fs.readFile(w.srtPath, 'utf8')).toBe(
      '1\n00:00:00,000 --> 00:00:03,400\nSpeaker 1: Hello. there.\nt0 t1\n\n',
    );
  });

  it('keeps the index + 1 binding with gaps; cueCount counts stored cues', async () => {
    const w = await SessionWriter.create(
      dir,
      meta('2026-11-05-session-1000'),
      undefined,
      { mergeMaxS: 10 },
    );
    for (const [index, text] of ['a', 'b', 'c'].entries()) {
      await w.appendSegment(index, {
        text,
        speaker: 'S',
        start_s: index,
        end_s: index + 1,
      });
    }
    await w.appendSegment(3, {
      text: 'd',
      speaker: 'T',
      start_s: 3,
      end_s: 4,
    });
    const srt = await fs.readFile(w.srtPath, 'utf8');
    expect(srt).toBe(
      '1\n00:00:00,000 --> 00:00:03,000\nS: a b c\n\n' +
        '4\n00:00:03,000 --> 00:00:04,000\nT: d\n\n',
    );
    expect(cueCount(srt)).toBe(2);
  });
});

