describe('transcript merge', () => {
  it('stores one merged cue for consecutive same-speaker finals when enabled', async () => {
    const provider2 = new FakeProvider();
    const app2 = await buildServer(
      parseConfig({
        STT_PROVIDER: 'deepgram',
        DEEPGRAM_API_KEY: 'dg',
        LLM_API_KEY: 'llm',
        TRANSCRIPT_MERGE_MAX_S: '5',
      }),
      {
        rootDir: dir,
        providerFactory: () => provider2,
        translatorFactory: () =>
          ({ translate: translateSpy }) as Translator,
        assistantFactory: () =>
          ({ analyze: assistSpy }) as AnswerAssistant,
      },
    );
    try {
      const res = await app2.inject({
        method: 'POST',
        url: '/api/sessions',
        payload: { diarize: true },
      });
      expect(res.statusCode).toBe(201);
      const info = res.json() as { id: string };
      const srtFile = srtPathFor(dir, info.id);

      provider2.emitFinal({
        text: 'Hello.',
        speaker: 'Speaker 1',
        start_s: 0,
        end_s: 2,
      });
      // the first final detours through renameSpeakers before its append,
      // so wait for the cue before emitting the next final
      await vi.waitFor(async () => {
        expect(await fs.readFile(srtFile, 'utf8')).toContain(
          '00:00:00,000 --> 00:00:02,000',
        );
      });
      provider2.emitFinal({
        text: 'there.',
        speaker: 'Speaker 1',
        start_s: 2,
        end_s: 3.4,
      });
      await vi.waitFor(async () => {
        const srt = await fs.readFile(srtFile, 'utf8');
        expect(srt).toContain('Hello. there.');
        expect(srt).toContain('XIN CHÀO XIN CHÀO');
      });

      await app2.inject({
        method: 'POST',
        url: `/api/sessions/${info.id}/stop`,
      });
      const read = await app2.inject({
        method: 'GET',
        url: `/api/sessions/${info.id}`,
      });
      const stored = read.json() as {
        srt: string;
        meta: { segments: number };
      };
      expect(stored.meta.segments).toBe(1);
      expect(stored.srt).toBe(
        '1\n00:00:00,000 --> 00:00:03,400\n' +
          'Speaker 1: Hello. there.\n' +
          'XIN CHÀO XIN CHÀO\n\n',
      );
    } finally {
      await app2.close();
    }
  });
});

